    "AH": {"expansion": "Authentication Header", "meaning": "IPSec protocol for integrity/authentication without encryption", "anchor": "acr-ah"},
    "AI": {"expansion": "Artificial Intelligence", "meaning": "Machine-based systems that simulate intelligent behaviour", "anchor": "acr-ai"},
    "AIS": {"expansion": "Automated Indicator Sharing", "meaning": "CISA service for exchanging threat indicators", "anchor": "acr-ais"},
    "ALE": {"expansion": "Annualized Loss Expectancy", "meaning": "SLE x ARO", "anchor": "acr-ale"},
    "AML": {"expansion": "Anti-Money Laundering", "meaning": "Financial-sector compliance rules; often paired with KYC checks", "anchor": "acr-aml"},
    "AP": {"expansion": "Access Point", "meaning": "Device that connects wireless clients to a network", "anchor": "acr-ap"},
    "API": {"expansion": "Application Programming Interface", "meaning": "Defined way for software components to communicate", "anchor": "acr-api"},
    "APK": {"expansion": "Android Package", "meaning": "Android app install file; sideloading APKs bypasses store vetting", "anchor": "acr-apk"},
    "APT": {"expansion": "Advanced Persistent Threat", "meaning": "Well-resourced, long-term, stealthy attacker", "anchor": "acr-apt"},
    "ARO": {"expansion": "Annualized Rate of Occurrence", "meaning": "Expected number of incidents per year", "anchor": "acr-aro"},
    "ARP": {"expansion": "Address Resolution Protocol", "meaning": "Maps IP addresses to MAC addresses", "anchor": "acr-arp"},
    "ASLR": {"expansion": "Address Space Layout Randomization", "meaning": "Randomizes memory addresses to hinder exploits", "anchor": "acr-aslr"},
