    "BASH": {"expansion": "Bourne Again Shell", "meaning": "Common Unix/Linux command shell", "anchor": "acr-bash"},
    "BCP": {"expansion": "Business Continuity Planning", "meaning": "Keeping critical functions running during disruption", "anchor": "acr-bcp"},
