    "BGP": {"expansion": "Border Gateway Protocol", "meaning": "Inter-domain internet routing protocol", "anchor": "acr-bgp"},
    "BIA": {"expansion": "Business Impact Analysis", "meaning": "Identifies critical functions and the impact of their loss", "anchor": "acr-bia"},
